import{_ as t,o,c as a,a0 as s}from"./chunks/framework.lnbZLl6b.js";const p=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Aquilifer","text":"A secure LLM provider for the web","tagline":"Websites ask Aquilifer for a completion. They never see your API key, only prompts in, answers out.","image":{"src":"/aquilaLarge.png","alt":"Aquilifer, a golden eagle standard"},"actions":[{"theme":"brand","text":"Get started","link":"/docs/"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/On0n0k1/aquilifer"}]},"features":[{"title":"For users","details":"Connect the LLM provider you actually want (Anthropic, OpenAI, or your own local/self-hosted model) once, from the extension's own settings. Choose which sites can use it, set your own usage limits, and keep a full log of every query made on your behalf."},{"title":"For developers","details":"window.aquilifer is all you need, no backend to stand up, deploy, or pay for. The user's own key pays for their own usage, not yours, and since there's no server-side state to keep, the rest of the site can stay entirely static."},{"title":"For companies","details":"Point it at your own internal or self-hosted model instead of a third-party API, with no code changes on the site's side. Apache 2.0 licensed, read it, audit it, fork it."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),r={name:"index.md"};function i(n,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><strong>A user installs Aquilifer</strong> and connects whichever LLM provider they want to use: an Anthropic API key, an OpenAI key, or a self-hosted endpoint like a local llama.cpp server. The credential is stored in the extension, nowhere else.</li><li><strong>A website asks for access</strong> through <code>window.aquilifer</code>. The first time, Aquilifer shows a plain-language approval prompt naming the site; the user approves or denies it.</li><li><strong>Once approved, the site can request completions</strong>, never the credential itself, never a way to change which provider answers. The user chose that when they connected it, and can revoke access at any time.</li></ol><p>Curious what that actually looks like in code? Head to the <a href="/projects/aquilifer/docs/">docs</a>.</p><h2 id="what-developers-get" tabindex="-1">What developers get <a class="header-anchor" href="#what-developers-get" aria-label="Permalink to &quot;What developers get&quot;">​</a></h2><ul><li><strong>No API bill.</strong> Every request runs on the user&#39;s own credential, not yours: no per-user cost to budget for, and no surprise invoice from a feature going viral.</li><li><strong>The user pays for their own usage</strong>, directly with their own provider account, the same as if they&#39;d typed the prompt into Claude or ChatGPT themselves.</li><li><strong>No dynamic state to hold.</strong> <code>window.aquilifer</code> runs entirely client-side, no backend proxy or session store just to keep a key off the client, so the rest of the site can stay 100% static.</li></ul><h2 id="what-users-get" tabindex="-1">What users get <a class="header-anchor" href="#what-users-get" aria-label="Permalink to &quot;What users get&quot;">​</a></h2><ul><li><strong>Control which LLM answers.</strong> Anthropic, OpenAI, or a self-hosted/local model, whichever you already trust and pay for, picked by you, not the site.</li><li><strong>Control your own usage.</strong> Set your own rate limits from the extension; a site can&#39;t run your spend past what you&#39;ve allowed it to.</li><li><strong>Local LLMs work too.</strong> Point Aquilifer at a local llama.cpp/Ollama/LM Studio server instead of a cloud API, and connected sites use it exactly the same way.</li><li><strong>See every query.</strong> A per-site, per-interface history log of every prompt and response, so you always know what was actually asked on your behalf.</li></ul><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>The usual way a website offers &quot;AI features&quot; is to run its own backend, hold an API key there, and proxy every request through it: infrastructure and cost the site owner carries even for a feature the <em>user</em> is the one who wants and would happily pay for with their own key. Aquilifer flips that: the browser extension is the trust boundary. The site never touches a credential; the user&#39;s key never leaves their own machine.</p><p>A site that wants this as a genuine fallback (its own integration first, Aquilifer only if that&#39;s unavailable) can do that too, without ever risking the user&#39;s spend limits or credentials.</p><p>Aquilifer is under active development; see the <a href="/projects/aquilifer/docs/">docs</a> for what&#39;s implemented today, and the <a href="/projects/aquilifer/docs/limitations">limitations page</a> for an honest look at what isn&#39;t yet.</p>',11)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
